		-- 1. 创建备份表，归档指定时间段数据
CREATE TABLE thorn_in_interface_backup 
AS SELECT * FROM thorn_in_interface tii 
WHERE  tii.CREATED_TIME < '2026-06-01';

-- 2. 校验备份行数（务必执行，确认备份数量和待删除数量一致，再删数据！）
SELECT COUNT(*) FROM thorn_in_interface_backup;
SELECT COUNT(*) FROM thorn_in_interface tii WHERE tii.CREATED_TIME < '2026-06-01'; 

-- 3. 删除原表对应时间段数据
DELETE FROM thorn_in_interface  tii WHERE tii.CREATED_TIME < '2026-06-01';
